use crate::*;
use alloc::vec::Vec;
use core::fmt;
use prns_groups_store::{CommitReceipt, StoreError};
use zeroize::Zeroizing;

/// Bound for one encrypted device receipt in this fixed MLS profile. Admission
/// reserves this many ciphertext bytes for each outstanding delivery target.
/// Receipts generated by the unpadded profile are smaller; oversized incoming
/// receipt envelopes are authenticated and rejected without consuming a reserve.
pub const MAX_RECEIPT_WIRE_BYTES: usize = 1024;

/// Caller-supplied authenticated, fixed-membership setup. All readers are MLS
/// members; delivery targets may select a subset without restricting decryption.
#[derive(Clone, Copy)]
pub struct Descriptor<'a> {
    pub group: GroupId,
    pub control: ControlReference,
    pub readers: &'a [Endpoint],
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Limits {
    pub max_records: usize,
    pub max_targets: usize,
    pub max_body_bytes: usize,
    pub max_changes: usize,
    /// Maximum accepted incoming and locally generated envelopes retained for relay.
    pub max_envelopes: usize,
    /// Maximum sum of exact retained MLS ciphertext lengths.
    pub max_retained_wire_bytes: usize,
    pub maximum_window: Seconds,
    pub future_skew: Seconds,
}

/// Exact request nonce retained with immutable publication facts.
pub type RecordNonce = [u8; 32];
/// Plaintext remains zeroized in the native domain. Foreign copies have the
/// receiving language's ownership rules.
pub type RecordBody = Zeroizing<Vec<u8>>;

pub struct Publication<'a> {
    pub nonce: RecordNonce,
    pub namespace: NamespaceId,
    pub schema: SchemaId,
    pub validity: PublicationValidity,
    pub targets: &'a [Endpoint],
    pub body: &'a [u8],
}

/// Durable plaintext application history has its own confidentiality/retention
/// policy; retiring an MLS ratchet key does not erase this retained body.
#[cfg_attr(feature = "uniffi-bindings", derive(uniffi::Record))]
#[cfg_attr(feature = "uniffi-bindings", uniffi(name = "GroupRecord"))]
pub struct Record {
    pub metadata: PublicationMetadata,
    pub nonce: RecordNonce,
    pub targets: Vec<Endpoint>,
    pub body: RecordBody,
}
impl fmt::Debug for Record {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Record")
            .field("metadata", &self.metadata)
            .field("targets", &self.targets.len())
            .field("body_bytes", &self.body.len())
            .finish_non_exhaustive()
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Fault {
    Allocation,
    InvalidEncoding,
    InvalidTargets,
    InvalidValidity,
    Capacity,
    Configuration,
    ConfigurationChanged,
    IdempotencyConflict,
    MissingRecord,
    UnknownOperation,
    EvidencePruned,
    UnsupportedControl,
    ApplicationStorageFault,
    Corrupt,
    TimeUncertain,
    Expired,
    RestartInventory,
}
#[derive(Debug)]
pub enum Error<E> {
    Fault(Fault),
    Store(StoreError<E>),
    Security(prns_groups_mls::Error<E>),
}
impl<E: fmt::Debug> fmt::Display for Error<E> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "group service error: {self:?}")
    }
}
impl<E: fmt::Debug> core::error::Error for Error<E> {}
impl<E> From<Fault> for Error<E> {
    fn from(value: Fault) -> Self {
        Self::Fault(value)
    }
}
impl<E> From<StoreError<E>> for Error<E> {
    fn from(value: StoreError<E>) -> Self {
        Self::Store(value)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Published {
    pub record: RecordId,
    pub commit: CommitReceipt,
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ReceiptOutput {
    pub record: RecordId,
    pub commit: CommitReceipt,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
#[cfg_attr(feature = "uniffi-bindings", derive(uniffi::Enum))]
#[cfg_attr(feature = "uniffi-bindings", uniffi(name = "GroupRejectReason"))]
pub enum RejectReason {
    InvalidPacket = 1,
    WrongGroup = 2,
    WrongAuthor = 3,
    WrongControl = 4,
    NotTargeted = 5,
    Expired = 6,
    TimeUncertain = 7,
    UnknownRecord = 8,
    InvalidReceipt = 9,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Incoming {
    Record(RecordId),
    Receipt(DurableReceipt),
    Rejected(RejectReason),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct ChangeCursor(pub u64);
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[cfg_attr(feature = "uniffi-bindings", derive(uniffi::Enum))]
#[cfg_attr(feature = "uniffi-bindings", uniffi(name = "GroupChangeKind"))]
pub enum ChangeKind {
    Published(RecordId),
    Received(RecordId),
    Receipt(DurableReceipt),
    ReceiptQueued(DurableReceipt),
    Rejected {
        envelope: EnvelopeId,
        reason: RejectReason,
    },
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[cfg_attr(feature = "uniffi-bindings", derive(uniffi::Record))]
#[cfg_attr(feature = "uniffi-bindings", uniffi(name = "GroupChange"))]
pub struct Change {
    pub cursor: ChangeCursor,
    pub operation: OperationId,
    pub kind: ChangeKind,
}
#[derive(Debug)]
pub struct ChangePage {
    pub changes: Vec<Change>,
    pub next: ChangeCursor,
    pub head: ChangeCursor,
}

/// A private inventory is available only to authenticated, authorized peers.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum InventoryKind {
    Record,
    Receipt,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct InventoryCursor(pub u64);

/// A fixed head within one persisted, append-only inventory generation.
/// New envelopes do not change a snapshot; a reinitialized store does.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct InventorySnapshot {
    pub generation: [u8; 32],
    pub head: InventoryCursor,
}

/// Authenticated locally stored facts, but only scheduling hints when received
/// from a remote inventory. MLS authentication still decides acceptance.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct EnvelopeInfo {
    pub position: InventoryCursor,
    pub id: EnvelopeId,
    pub kind: InventoryKind,
    pub record: RecordId,
    pub bytes: usize,
}

#[derive(Debug)]
pub struct InventoryPage {
    pub items: Vec<EnvelopeInfo>,
    /// Advances over scanned entries, including entries excluded by the filter.
    pub next: InventoryCursor,
    pub snapshot: InventorySnapshot,
}
